def decide(recipient_reputation, round_num, my_history):
    # Base threshold: decreasing with round (more forgiving over time)
    base_threshold = 0.4 - 0.06 * round_num
    # Clamp to reasonable range
    base_threshold = max(-0.6, min(0.5, base_threshold))

    # Adjust threshold based on personal history (how often we have cooperated)
    if len(my_history) > 0:
        coop_ratio = sum(1 for action in my_history if action) / len(my_history)
        if coop_ratio > 0.7:
            # If we have been very cooperative, be more generous (lower threshold)
            threshold = base_threshold - 0.2
        elif coop_ratio < 0.3:
            # If we have been very defective, be more demanding (raise threshold)
            threshold = base_threshold + 0.2
        else:
            threshold = base_threshold
    else:
        threshold = base_threshold

    # Decide: cooperate if reputation meets or exceeds threshold
    return recipient_reputation >= threshold
